    // DIAGNOSTIC VERSION: Safe getCookie with logging
    function getLIUserCookie() {
        var name = "userinfo=";
        var ca = document.cookie.split(';'); // Split raw cookies first (Safe)

        for (var i = 0; i < ca.length; i++) {
            var c = ca[i];
            while (c.charAt(0) == ' ') c = c.substring(1);

            if (c.indexOf(name) == 0) {
                // We found the raw cookie string
                var rawVal = c.substring(name.length, c.length);

                // Attempt to decode
                try {
                    var decodedVal = decodeURIComponent(rawVal);
                    // Check if it looks like it's still encoded (Diagnostic check)
                    if (decodedVal.indexOf('%3A') > -1 || decodedVal.indexOf('%7B') > -1) {
                         console.warn("EVG_DEBUG: Cookie found but appears Double Encoded:", decodedVal);
                    }
                    return decodedVal;
                } catch (e) {
                    console.error("EVG_DEBUG: Critical Failure - Cookie exists but is Malformed (URIError). Raw value:", rawVal);
                    return ""; // Return empty to prevent crash downstream
                }
            }
        }
        return "";
    }

    async function apply(context, template) {
        console.log('EVG_DEBUG: Template Starting');

        var userinfocookie = getLIUserCookie();

        if (!userinfocookie) {
             console.log("EVG_DEBUG: Userinfo cookie not found or empty.");
             return; 
        }

        // Safe Parsing Block
        var userinfo;
        try {
            userinfo = JSON.parse(userinfocookie);
            console.log('EVG_DEBUG: User Attributes Parsed Successfully:', userinfo);
        } catch (e) {
            console.error("EVG_DEBUG: JSON PARSE ERROR. The script stopped here.");
            console.error("EVG_DEBUG: Error Details:", e.message);
            console.error("EVG_DEBUG: The string we tried to parse was:", userinfocookie);
            return; // Stop execution safely
        }

        // Logic continues only if parse succeeded
        try {
            var data = {
                "userId": userinfo.userId,
                "token": userinfo.token
            };

            var response = await fetch("/CmeWS/mvc/secured/UserAccount/salesforce-userinfo", {
                method: "POST",
                body: JSON.stringify(data),
                headers: {
                    'Content-Type': 'application/json;charset=UTF-8',
                },
            });

            if (!response.ok) {
                console.error("EVG_DEBUG: API Error. Status:", response.status);
                return;
            }

            var output = await response.json();

            // Push to DataLayer
            window.dataLayer = window.dataLayer || [];
            window.dataLayer.push({
                'event': 'salesforceinfo',
                'data': output
            });

            // Null checks with defaulting
            var productGroup = output.Self_Input_Product_Group__c || 'Not Set';
            var markets = output.Self_Input_Markets_Currently_Trading__c || 'Not Set';
            var tradeClear = output.Self_Input_Do_you_currently_trade_clear__c || 'Not Set';

            Evergage.sendEvent({
                action: "Salesforce Data Retrieval",
                user: {
                    attributes: {
                        MatchedAccount: output.Matched_Account__c,
                        sfmcContactKey: output.Id,
                        primaryProductInterest: productGroup,
                        MarketsCurrentlyTrading: markets,
                        CurrentlyTrade: tradeClear
                    },
                    identities: {
                        sfmcContactKey: output.Id
                    }
                }
            });

            // Setup listeners
            var primaryProductSelect = document.getElementById('primaryProduct');
            if (primaryProductSelect) {
                primaryProductSelect.addEventListener('change', function () {
                     // Define update function inline or ensure it's in scope
                     Evergage.sendEvent({
                        action: "Salesforce Data Retrieval - Update",
                        user: {
                            attributes: { primaryProductInterest: this.value }
                        }
                    });
                });
            }

        } catch (err) {
            console.error("EVG_DEBUG: Unexpected error in API/Fetch flow:", err);
        }
    }

    function reset(context, template) {}
    function control(context) {}

    registerTemplate({
        apply: apply,
        reset: reset,
        control: control
    });
})(); 
